package org.dpdns.gmm;
import android.os.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Same product command/art renderer with shared-human transport; never invokes AI endpoints. */
final class NativeRoster60PvpBattle extends NativeRoster60Battle {
 final Handler poll=new Handler(Looper.getMainLooper());JSONObject initial;boolean paused;Button accept,decline,waitingSurrender;
 NativeRoster60PvpBattle(MainActivity h,JSONObject initial){super(h);this.initial=initial;}
 @Override String storageScope(){return "|human-pvp";}
 @Override void open(){super.open();if(!current())return;LinearLayout controls=(LinearLayout)settle.getParent();accept=h.button("대전 수락",()->accept(true));decline=h.button("대전 거절",()->accept(false));waitingSurrender=h.button("항복 · 경험치 0",()->command(h.obj("kind","escape")));controls.addView(accept,new LinearLayout.LayoutParams(0,h.dp(48),1));controls.addView(decline,new LinearLayout.LayoutParams(0,h.dp(48),1));controls.addView(waitingSurrender,new LinearLayout.LayoutParams(0,h.dp(48),1));if(view!=null)bind(view);}
 @Override void resume(){paused=false;if(!current()||reading||(selection!=null&&selection.isShowing())){schedule();return;}String pending=prefs.getString(key+":pending","");if(!pending.isEmpty()){try{send(new JSONObject(pending));}catch(JSONException bad){error("저장된 대전 요청 확인 필요");}return;}if(initial!=null){JSONObject value=initial;initial=null;bind(value);schedule();return;}reading=true;h.api.call("native/roster60/pvp/current",null,(r,e)->{reading=false;if(!current())return;if(e!=null){error(e);schedule();return;}JSONObject b=r.optJSONObject("battle");if(b!=null)bind(b);else{pause();h.openRosterPvp();return;}schedule();});}
 @Override void read(String id){resume();}
 @Override void options(){h.openRosterPvp();}
 void accept(boolean value){if(view!=null)mutate("accept",h.obj("battleId",view.optString("battleId"),"revision",view.optInt("revision"),"accept",value));}
 @Override void send(JSONObject intent){JSONObject body=intent.optJSONObject("body");if(body==null)return;String id=body.optString("requestId"),op=intent.optString("operation");if(!Arrays.asList("action","settle","accept").contains(op)||id.isEmpty()){error("저장된 대전 요청 확인 필요");return;}if(!IN_FLIGHT.add(id)){message.setText("대전 요청 결과 확인 중…");schedule();return;}panel.lock();settle.setEnabled(false);if(accept!=null){accept.setEnabled(false);decline.setEnabled(false);waitingSurrender.setEnabled(false);}
 h.api.call("native/roster60/pvp/"+op,body,(r,e)->{IN_FLIGHT.remove(id);if(!owner.equals(h.api.token()))return;boolean rejected=e!=null&&(e.contains("PENDING")||Arrays.asList("STALE_REVISION","PVP_NOT_FOUND","BATTLE_NOT_FOUND","BATTLE_FINISHED","BATTLE_NOT_FINISHED","INVALID_ACTION","INVALID_REQUEST","REQUEST_ID_REUSED","FORCED_SWITCH_REQUIRED","INVALID_SWITCH","INVALID_ITEM","INVALID_ITEM_TARGET","ITEM_UNAVAILABLE","NO_STATUS_TO_CLEANSE","HP_FULL","INSUFFICIENT_MP","SKILL_NOT_EQUIPPED","ACTION_ALREADY_SUBMITTED","ACCEPTANCE_REQUIRED","OPPONENT_FORCED_SWITCH","PVP_BUSY","PARTY_REQUIRED").contains(e));if(e==null||rejected)prefs.edit().remove(key+":pending").commit();if(!current())return;if(e!=null){if("settle".equals(op))settlementError=e;error(e);if(rejected&&!"settle".equals(op))resume();else schedule();return;}JSONObject b=r.optJSONObject("battle");bind(b==null?r:b);schedule();});}
 @Override void bind(JSONObject r){
 if(r.optBoolean("requeued")){pause();h.openRosterPvp();return;}
 if("ACCEPTING".equals(r.optString("status"))){view=r;panel.lock();panel.setVisibility(android.view.View.GONE);stats.setVisibility(android.view.View.VISIBLE);settle.setEnabled(false);settle.setVisibility(android.view.View.GONE);retry.setVisibility(android.view.View.GONE);stats.setText("실제 사용자 대전 · 양쪽 수락 후 전투 시작");long seconds=Math.max(0,(r.optLong("deadline")-System.currentTimeMillis()+999)/1000);message.setText((r.optBoolean("accepted")?"상대 수락 대기":"대전을 수락해 주세요")+" · "+seconds+"초");if(accept!=null){accept.setVisibility(android.view.View.VISIBLE);decline.setVisibility(android.view.View.VISIBLE);accept.setEnabled(!r.optBoolean("accepted")&&prefs.getString(key+":pending","").isEmpty());decline.setEnabled(prefs.getString(key+":pending","").isEmpty());waitingSurrender.setVisibility(android.view.View.GONE);}return;}
 super.bind(r);if(view==null)return;boolean active="ACTIVE".equals(r.optString("status")),waiting=r.optBoolean("waitingForOpponent");settle.setVisibility(settlementError.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);if(accept!=null){accept.setVisibility(android.view.View.GONE);decline.setVisibility(android.view.View.GONE);waitingSurrender.setVisibility(active&&waiting?android.view.View.VISIBLE:android.view.View.GONE);waitingSurrender.setEnabled(active&&prefs.getString(key+":pending","").isEmpty());}
 if(waiting){panel.lock();message.setText(r.optJSONObject("state").optJSONArray("fighters").optJSONObject(1).optInt("hp")<=0?"상대 강제 교체 대기 중":"선택 완료 · 상대 선택 대기\n상대 선택 비공개");}else if(active&&r.optJSONObject("state").optJSONArray("fighters").optJSONObject(0).optInt("hp")>0)message.setText("대전 · 턴 "+r.optJSONObject("state").optInt("turn"));if(!prefs.getString(key+":pending","").isEmpty())panel.lock();if("SETTLED".equals(r.optString("status"))){retry.setText("대전 목록");retry.setOnClickListener(v->{pause();h.openRosterPvp();});}else{retry.setVisibility(android.view.View.GONE);retry.setText("연결 재시도");retry.setOnClickListener(v->resume());}
 }
 void schedule(){poll.removeCallbacksAndMessages(null);if(current()&&!paused)poll.postDelayed(this::resume,1500);}
 @Override void pause(){paused=true;poll.removeCallbacksAndMessages(null);super.pause();}
 @Override boolean back(){if(panel!=null){panel.cancelInteraction();if(panel.showCommands())return true;}pause();h.home();return true;}
}
